import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');
const write = (p, value) => { const target = path.join(root, p); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, value); };
const write64 = (p, value) => write(p, Buffer.from(value, 'base64').toString('utf8'));
const replaceExact = (p, oldValue, newValue, label) => {
  const source = read(p);
  if (!source.includes(oldValue)) throw new Error(`STOP: ${label || p} pattern not found`);
  write(p, source.replace(oldValue, newValue));
};
const replaceAllExact = (p, pairs) => { let source = read(p); for (const [oldValue, newValue, label] of pairs) { if (!source.includes(oldValue)) throw new Error(`STOP: ${label || p} pattern not found`); source = source.replaceAll(oldValue, newValue); } write(p, source); };

